          <svg width="60" height="60" viewBox="0 0 24 24" fill="none" stroke="#bbb" stroke-width="1.5"><circle cx="12" cy="7" r="4"/><path d="M4 21c0-4.418 3.582-8 8-8s8 3.582 8 8"/></svg>
        </div>
        <div class="card-body">
          <div class="card-cats"><span>Hunde</span><span>Erziehung</span></div>
          <div class="card-date">15. Mai 2026</div>
