      <article class="blog-card">
        <div class="card-img">
          <svg width="60" height="60" viewBox="0 0 24 24" fill="none" stroke="#bbb" stroke-width="1.5"><path d="M12 5c-3.866 0-7 2.686-7 6s3.134 6 7 6 7-2.686 7-6-3.134-6-7-6z"/><path d="M12 9v4"/><path d="M10 11h4"/></svg>
        </div>
        <div class="card-body">
          <div class="card-cats"><span>Katzen</span><span>Wohnungshaltung</span></div>
          <div class="card-date">8. Mai 2026</div>
