    <p>Hier wird eine responsive Anzeige eingeblendet.</p>
  </div>
</main>

<footer class="site-footer">
  <div class="footer-wrap">
    <div>
      <strong style="color:#fff;">🐾 Haustierzentrum</strong>
      <p style="margin-top:.3rem;">Dein Blog für artgerechte Haustierhaltung</p>
    </div>
