{"path": "C:\HermesPortable\home\scripts\blog-automation\haustier-zentrum\generate_sketch_images.py", "content": "#!/usr/bin/env python3
"""
Generate colored pencil sketch style hero images for all Haustierzentrum articles.
Uses ComfyUI API at localhost:8188 with SDXL base model.
"""
import json, os, sys, time, uuid, requests
from pathlib import Path

API_BASE = "http://127.0.0.1:8188"
OUTPUT_DIR = Path(__file__).parent / "images"
CLIENT_ID = str(uuid.uuid4())

WORKFLOW_TEMPLATE = {
    "3": {
        "class_type": "KSampler",
        "inputs": {
            "seed": 42,
            "steps": 25,
            "cfg": 7,
            "sampler_name": "euler",
            "scheduler": "normal",
            "denoise": 1,
            "model": ["4", 0],
            "positive": ["6", 0],
            "negative": ["7", 0],
            "latent_image": ["5", 0]
        }
    },
    "4": {
        "class_type": "CheckpointLoaderSimple",
        "inputs": {
            "ckpt_name": "sd_xl_base_1.0.safetensors"
        }
    },
    "5": {
        "class_type": "EmptyLatentImage",
        "inputs": {
            "width": 1024,
            "height": 768,
            "batch_size": 1
        }
    },
    "6": {
        "class_type": "CLIPTextEncode",
        "inputs": {
            "text": "",
            "clip": ["4", 1]
        }
    },
    "7": {
        "class_type": "CLIPTextEncode",
        "inputs": {
            "text": "photorealistic, 3d render, photograph, realistic texture, hyperrealistic, cinematic lighting, shadows, gradient, oil painting, airbrush, digital art, smooth shading",
            "clip": ["4", 1]
        }
    },
    "8": {
        "class_type": "VAEDecode",
        "inputs": {
            "samples": ["3", 0],
            "vae": ["4", 2]
        }
    },
    "9": {
        "class_type": "SaveImage",
        "inputs": {
            "filename_prefix": "comfy",
            "images": ["8", 0]
        }
    }
}

def queue_prompt(prompt, seed):
    """Queue a prompt via ComfyUI API."""
    workflow = json.loads(json.dumps(WORKFLOW_TEMPLATE))
    workflow["3"]["inputs"]["seed"] = seed
    workflow["6"]["inputs"]["text"] = prompt

    payload = {
        "prompt": workflow,
        "client_id": CLIENT_ID
    }

    r = requests.post(f"{API_BASE}/prompt", json=payload)
    r.raise_for_status()
    return r.json()["prompt_id"]

def wait_for_image(prompt_id, timeout=120):
    """Wait for generation to complete and return image path."""
    start = time.time()
    history_url = f"{API_BASE}/history/{prompt_id}"

    while time.time() - start < timeout:
        r = requests.get(history_url)
        if r.status_code == 200 and prompt_id in r.json():
            data = r.json()[prompt_id]
            outputs = data.get("outputs", {})
            for node_id, node_out in outputs.items():
                for img_data in node_out.get("images", []):
                    return img_data["filename"]
            return None
        time.sleep(2)
    raise TimeoutError("Image generation timed out")

def main():
