<html lang="de">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>Haustierzentrum – Ratgeber für Hunde, Katzen & Kleintiere</title>
<meta name="description" content="Haustierzentrum – Ihr Blog für artgerechte Haustierhaltung. Tipps zu Hunden, Katzen, Hamstern, Meerschweinchen und mehr.">
<meta property="og:title" content="Haustierzentrum – Haustier-Ratgeber">
<meta property="og:description" content="Tipps und Ratgeber für eine glückliche Haustierhaltung.">
<meta property="og:url" content="https://haustierzentrum.com">
<meta property="og:type" content="website">
<meta property="og:site_name" content="Haustierzentrum">
<meta name="robots" content="index, follow">
<link rel="canonical" href="https://haustierzentrum.com">
<script type="application/ld+json">
{
  "@context": "https://schema.org",
  "@type": "Blog",
  "name": "Haustierzentrum",
  "description": "Ratgeber für artgerechte Haustierhaltung – Hunde, Katzen, Kleintiere.",
  "url": "https://haustierzentrum.com",
  "author": {
    "@type": "Person",
    "name": "Haustierzentrum Redaktion"
  }
}
</script>
<style>
:root {
  --primary: #FF9800;
  --primary-dark: #e68900;
  --bg: #ffffff;
  --bg-alt: #f7f7f7;
  --text: #1a1a1a;
  --text-muted: #666;
  --border: #e0e0e0;
  --card-shadow: 0 2px 12px rgba(0,0,0,.08);
  --font: system-ui, -apple-system, 'Segoe UI', Roboto, sans-serif;
}
*,*::before,*::after{box-sizing:border-box;margin:0;padding:0}
html{scroll-behavior:smooth}
body{
  font-family:var(--font);
  color:var(--text);
  background:var(--bg);
  line-height:1.7;
  display:flex;
  flex-direction:column;
  min-height:100vh;
}
a{color:var(--primary);text-decoration:none}
a:hover{text-decoration:underline}
img{max-width:100%;height:auto;display:block}

/* Header / Nav */
.site-header{
  background:var(--bg);
  border-bottom:2px solid var(--primary);
  padding:0 1rem;
  position:sticky;
  top:0;
  z-index:100;
}
.nav-wrap{
  max-width:1100px;
  margin:0 auto;
  display:flex;
  align-items:center;
  justify-content:space-between;
  height:64px;
}
.logo{
  font-size:1.4rem;
  font-weight:800;
  color:var(--primary);
  letter-spacing:-.5px;
}
.logo:hover{text-decoration:none}
.nav-links{display:flex;gap:1.5rem;list-style:none}
.nav-links a{
  color:var(--text);
  font-weight:500;
  font-size:.95rem;
  padding:.3rem 0;
  border-bottom:2px solid transparent;
  transition:.2s;
}
.nav-links a:hover,.nav-links a.active{
  color:var(--primary);
  border-bottom-color:var(--primary);
  text-decoration:none;
}
.nav-toggle{display:none;background:none;border:none;font-size:1.6rem;cursor:pointer;color:var(--text);padding:.25rem;}

/* Main */
main{flex:1;max-width:1100px;margin:0 auto;padding:2rem 1rem;width:100%}

/* Hero */
.hero{
  background:linear-gradient(135deg,#fff3e0,#ffe0b2);
  border-radius:16px;
  padding:3rem 2rem;
  margin-bottom:3rem;
  text-align:center;
}
.hero h1{font-size:2.2rem;margin-bottom:.5rem;color:var(--primary-dark)}
.hero p{font-size:1.1rem;color:var(--text-muted);max-width:600px;margin:0 auto}

/* Cards */
.blog-grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(320px,1fr));gap:2rem;margin-bottom:3rem}
.blog-card{
  background:var(--bg);
  border:1px solid var(--border);
  border-radius:12px;
  overflow:hidden;
  box-shadow:var(--card-shadow);
  transition:transform .2s,box-shadow .2s;
  display:flex;
  flex-direction:column;
}
.blog-card:hover{transform:translateY(-4px);box-shadow:0 6px 24px rgba(0,0,0,.12)}
.card-img{
  width:100%;
  height:200px;
  background:var(--bg-alt);
  display:flex;
  align-items:center;
  justify-content:center;
  color:var(--text-muted);
  font-size:.9rem;
  border-bottom:1px solid var(--border);
  overflow:hidden;
}
.card-img img{width:100%;height:100%;object-fit:cover}
.card-body{padding:1.5rem;flex:1;display:flex;flex-direction:column}
.card-cats{display:flex;gap:.5rem;flex-wrap:wrap;margin-bottom:.7rem}
.card-cats span{
  background:var(--primary);
  color:#fff;
  font-size:.75rem;
  font-weight:600;
  padding:.2rem .7rem;
  border-radius:20px;
  text-transform:uppercase;
  letter-spacing:.3px;
}
.card-date{font-size:.82rem;color:var(--text-muted);margin-bottom:.5rem}
.card-body h2{font-size:1.2rem;margin-bottom:.6rem;line-height:1.4}
.card-body h2 a{color:var(--text)}
.card-body h2 a:hover{color:var(--primary);text-decoration:none}
.card-body p{color:var(--text-muted);font-size:.92rem;flex:1;margin-bottom:1rem}
.card-body .read-more{
  align-self:flex-start;
  font-weight:600;
  color:var(--primary);
  font-size:.9rem;
}
.card-body .read-more:hover{text-decoration:underline}

/* Article page */
.article-header{margin-bottom:2rem}
.article-header h1{font-size:2rem;line-height:1.3;margin-bottom:.5rem}
.article-meta{display:flex;gap:1rem;flex-wrap:wrap;align-items:center;font-size:.88rem;color:var(--text-muted);margin-bottom:1rem}
.article-meta .cats span{background:var(--primary);color:#fff;font-size:.75rem;font-weight:600;padding:.2rem .7rem;border-radius:20px;margin-right:.4rem}
.featured-img{
  width:100%;
  max-height:420px;
  background:var(--bg-alt);
  border-radius:12px;
  display:flex;
  align-items:center;
  justify-content:center;
  color:var(--text-muted);
  margin-bottom:2rem;
  overflow:hidden;
}
.featured-img img{width:100%;height:100%;object-fit:cover}
.article-content{max-width:750px;margin:0 auto}
.article-content h2{font-size:1.5rem;margin:2rem 0 1rem;color:var(--primary-dark)}
.article-content h3{font-size:1.2rem;margin:1.5rem 0 .8rem}
.article-content p{margin-bottom:1.2rem}
.article-content ul,.article-content ol{margin-bottom:1.2rem;padding-left:1.5rem}
.article-content li{margin-bottom:.4rem}

/* Ad / Affiliate placeholders */
.ad-placeholder{
  background:var(--bg-alt);
  border:2px dashed var(--border);
  border-radius:8px;
  padding:2rem;
  text-align:center;
  margin:2rem 0;
  color:var(--text-muted);
  font-size:.85rem;
}
.ad-placeholder.amazon{
  border-color:var(--primary);
  background:#fff8e1;
}

/* Info pages */
.info-page{max-width:780px;margin:0 auto}
.info-page h1{font-size:2rem;margin-bottom:1rem;color:var(--primary-dark)}
.info-page h2{font-size:1.3rem;margin:2rem 0 .8rem}
.info-page p{margin-bottom:1rem}

/* Footer */
.site-footer{
  background:#1a1a1a;
  color:#ccc;
  padding:2rem 1rem;
  margin-top:3rem;
  font-size:.88rem;
}
.footer-wrap{
  max-width:1100px;
  margin:0 auto;
  display:flex;
  flex-wrap:wrap;
  gap:2rem;
  justify-content:space-between;
  align-items:center;
}
.footer-wrap a{color:#FFB74D}
.footer-wrap a:hover{color:#fff}
.footer-copy{text-align:center;width:100%;margin-top:1rem;padding-top:1rem;border-top:1px solid #333;font-size:.82rem}

/* Cookie banner */
.cookie-banner{
  position:fixed;
  bottom:0;
  left:0;
  right:0;
  background:#1a1a1a;
  color:#eee;
  padding:1rem 1.5rem;
  display:none;
  z-index:999;
  box-shadow:0 -4px 20px rgba(0,0,0,.3);
  font-size:.9rem;
}
.cookie-banner.show{display:flex;flex-wrap:wrap;align-items:center;justify-content:center;gap:1rem}
.cookie-banner p{max-width:700px}
.cookie-banner button{
  background:var(--primary);
  border:none;
  color:#fff;
  font-weight:600;
  padding:.5rem 1.5rem;
  border-radius:6px;
  cursor:pointer;
  font-size:.9rem;
  white-space:nowrap;
}
.cookie-banner button:hover{background:var(--primary-dark)}

/* Sitemap helpers */
.sitemap-list{list-style:none;padding:0}
.sitemap-list li{margin-bottom:.5rem}
.sitemap-list a{font-weight:500}

/* Responsive */
@media(max-width:768px){
  .nav-links{
    display:none;
    position:absolute;
    top:64px;
    left:0;
    right:0;
    background:var(--bg);
    flex-direction:column;
    padding:1rem;
    border-bottom:2px solid var(--primary);
    box-shadow:0 4px 12px rgba(0,0,0,.1);
    gap:.25rem;
  }
  .nav-links.open{display:flex}
  .nav-toggle{display:block}
  .hero h1{font-size:1.7rem}
  .hero{padding:2rem 1rem}
  .blog-grid{grid-template-columns:1fr}
  .article-header h1{font-size:1.5rem}
  .cookie-banner{flex-direction:column;text-align:center}
}
</style>
</head>
