{"new_string": ":root {
  --primary: #FF9800;
  --primary-dark: #e68900;
  --primary-light: #ffe0b2;
  --bg: #faf8f3;
  --bg-alt: #f0ece1;
  --text: #2d2d2d;
  --text-muted: #7a7a7a;
  --border: #e0d8c8;
  --card-shadow: 0 4px 20px rgba(0,0,0,.07);
  --font: 'Segoe UI', system-ui, -apple-system, sans-serif;
  --sketch-border: 3px dashed var(--primary-light);
}
*,*::before,*::after{box-sizing:border-box;margin:0;padding:0}
html{scroll-behavior:smooth}
body{
  font-family:var(--font);
  color:var(--text);
  background:var(--bg);
  background-image: radial-gradient(circle at 25px 25px, #e8e3d6 1px, transparent 1px);
  background-size: 50px 50px;
  line-height:1.7;
  display:flex;
  flex-direction:column;
  min-height:100vh;
}
a{color:var(--primary);text-decoration:none}
a:hover{text-decoration:underline}
img{max-width:100%;height:auto;display:block}

/* Header / Nav */
.site-header{
  background:rgba(255,255,255,.95);
  backdrop-filter:blur(10px);
  border-bottom:3px solid var(--primary);
  padding:0 1rem;
  position:sticky;
  top:0;
  z-index:100;
}
.nav-wrap{
  max-width:1100px;
  margin:0 auto;
  display:flex;
  align-items:center;
  justify-content:space-between;
  height:68px;
}
.logo{
  font-size:1.5rem;
  font-weight:900;
  color:var(--primary-dark);
  letter-spacing:-1px;
  background:linear-gradient(135deg,var(--primary-dark),var(--primary));
  -webkit-background-clip:text;
  -webkit-text-fill-color:transparent;
  background-clip:text;
}
.logo:hover{text-decoration:none}
.nav-links{display:flex;gap:1.5rem;list-style:none}
.nav-links a{
  color:var(--text);
  font-weight:600;
  font-size:.9rem;
  padding:.35rem .85rem;
  border-radius:50px;
  transition:.2s;
}
.nav-links a:hover,.nav-links a.active{
  color:#fff;
  background:var(--primary);
  text-decoration:none;
}
.nav-toggle{display:none;background:none;border:none;font-size:1.6rem;cursor:pointer;color:var(--text);padding:.25rem;}

/* Main */
main{flex:1;max-width:1100px;margin:0 auto;padding:2rem 1rem;width:100%}

/* Hero */
.hero{
  background:linear-gradient(135deg,#fff3e0,#ffe0b2);
  border-radius:24px;
  padding:3.5rem 2rem;
  margin-bottom:3rem;
  text-align:center;
  position:relative;
  overflow:hidden;
  border:var(--sketch-border);
}
.hero::before{
  content:'';
  position:absolute;
  top:-50px;right:-50px;
  width:200px;height:200px;
  background:radial-gradient(circle,rgba(255,152,0,.12) 0%,transparent 70%);
  border-radius:50%;
}
.hero::after{
  content:'';
  position:absolute;
  bottom:-30px;left:-30px;
  width:150px;height:150px;
  background:radial-gradient(circle,rgba(255,152,0,.08) 0%,transparent 70%);
  border-radius:50%;
}
.hero h1{font-size:2.4rem;margin-bottom:.5rem;color:var(--primary-dark);position:relative;z-index:1}
.hero p{font-size:1.15rem;color:var(--text-muted);max-width:600px;margin:0 auto;position:relative;z-index:1}

/* Section headings */
.section-heading{
  font-size:1.6rem;
  font-weight:800;
  color:var(--primary-dark);
  margin-bottom:1.5rem;
  padding-bottom:.5rem;
  border-bottom:3px solid var(--primary-light);
  display:inline-block;
}

/* Cards */
.blog-grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(300px,1fr));gap:1.8rem;margin-bottom:3rem}
.blog-card{
  background:#fff;
  border:2px solid var(--border);
  border-radius:16px;
  overflow:hidden;
  box-shadow:var(--card-shadow);
  transition:transform .25s,box-shadow .25s;
  display:flex;
  flex-direction:column;
  position:relative;
}
.blog-card:hover{transform:translateY(-6px);box-shadow:0 8px 32px rgba(0,0,0,.1)}
.blog-card::after{
  content:'';
  position:absolute;
  inset:0;
  border-radius:14px;
  border:2px dashed transparent;
  transition:.25s;
  pointer-events:none;
}
.blog-card:hover::after{border-color:var(--primary-light);}
.card-img{
  width:100%;
  height:200px;
  background:var(--bg-alt);
  display:flex;
  align-items:center;
  justify-content:center;
  overflow:hidden;
}
.card-img img{width:100%;height:100%;object-fit:cover;transition:transform .4s}
.blog-card:hover .card-img img{transform:scale(1.05)}
.card-body{padding:1.3rem 1.5rem;flex:1;display:flex;flex-direction:column}
.card-cats{display:flex;gap:.4rem;flex-wrap:wrap;margin-bottom:.6rem}
.card-cats span{
  background:var(--primary);
  color:#fff;
  font-size:.7rem;
  font-weight:700;
  padding:.2rem .7rem;
  border-radius:50px;
  text-transform:uppercase;
  letter-spacing:.5px;
}
.card-date{font-size:.8rem;color:var(--text-muted);margin-bottom:.4rem}
.card-body h2{font-size:1.15rem;margin-bottom:.5rem;line-height:1.35}
.card-body h2 a{color:var(--text)}
.card-body h2 a:hover{color:var(--primary);text-decoration:none}
.card-body p{color:var(--text-muted);font-size:.88rem;flex:1;margin-bottom:.8rem;line-height:1.55}
.card-body .read-more{
  align-self:flex-start;
  font-weight:700;
  color:var(--primary);
  font-size:.85rem;
  padding:.3rem 0;
  border-bottom:2px solid transparent;
  transition:.2s;
}
.card-body .read-more:hover{border-bottom-color:var(--primary);text-decoration:none}

/* Ad / Affiliate placeholders */
.ad-placeholder{
  background:var(--bg-alt);
  border:3px dashed var(--border);
  border-radius:12px;
  padding:2rem;
  text-align:center;
  margin:2rem 0;
  color:var(--text-muted);
  font-size:.85rem;
}
.ad-placeholder.amazon{
  border-color:var(--primary);
  background:#fff8e1;
}

/* Footer */
.site-footer{
  background:#2d2d2d;
  color:#bbb;
  padding:2.5rem 1rem;
  margin-top:3rem;
  font-size:.88rem;
}
.footer-wrap{
  max-width:1100px;
  margin:0 auto;
  display:flex;
  flex-wrap:wrap;
  gap:2rem;
  justify-content:space-between;
  align-items:center;
}
.footer-wrap a{color:#FFB74D}
.footer-wrap a:hover{color:#fff}
.footer-copy{text-align:center;width:100%;margin-top:1rem;padding-top:1rem;border-top:1px solid #444;font-size:.82rem}

/* Cookie banner */
.cookie-banner{
  position:fixed;
  bottom:0;
  left:0;
  right:0;
  background:#2d2d2d;
  color:#eee;
  padding:1rem 1.5rem;
  display:none;
  z-index:999;
  box-shadow:0 -4px 20px rgba(0,0,0,.3);
  font-size:.9rem;
}
.cookie-banner.show{display:flex;flex-wrap:wrap;align-items:center;justify-content:center;gap:1rem}
.cookie-banner p{max-width:700px}
.cookie-banner button{
  background:var(--primary);
  border:none;
  color:#fff;
  font-weight:700;
  padding:.5rem 1.5rem;
  border-radius:50px;
  cursor:pointer;
  font-size:.9rem;
  white-space:nowrap;
}
.cookie-banner button:hover{background:var(--primary-dark)}

/* Responsive */
@media(max-width:768px){
  .nav-links{
    display:none;
    position:absolute;
    top:68px;
    left:0;
    right:0;
    background:rgba(255,255,255,.98);
    flex-direction:column;
    padding:.5rem;
    border-bottom:3px solid var(--primary);
    box-shadow:0 4px 12px rgba(0,0,0,.1);
    gap:0;
