@import url('https://fonts.googleapis.com/css2?family=DM+Sans:opsz,wght@9..40,300;9..40,400;9..40,500;9..40,600;9..40,700;9..40,800;9..40,900&family=DM+Serif+Display:ital@0;1&display=swap');

:root {
  --primary: #FF9800;
  --primary-dark: #e67e00;
  --primary-light: #fff3e0;
  --primary-glow: rgba(255,152,0,.15);
  --bg: #faf8f3;
  --bg-alt: #f0ece1;
  --bg-white: #ffffff;
  --text: #1e1e1e;
  --text-muted: #7a7a7a;
  --text-light: #b0a8a0;
  --border: #e0d8c8;
  --border-light: #f0ece1;
  --card-shadow: 0 4px 24px rgba(0,0,0,.06);
  --card-shadow-hover: 0 12px 48px rgba(0,0,0,.1);
  --font: 'DM Sans', system-ui, -apple-system, sans-serif;
  --font-display: 'DM Serif Display', Georgia, serif;
  --sketch: 3px dashed var(--primary-light);
  --radius-sm: 8px;
  --radius-md: 16px;
  --radius-lg: 24px;
  --radius-xl: 32px;
}
*,*::before,*::after{box-sizing:border-box;margin:0;padding:0}
html{scroll-behavior:smooth}

/* --- BODY --- */
body{
  font-family:var(--font);
  color:var(--text);
  background:var(--bg);
  background-image:
    radial-gradient(circle at 18px 18px, #e8e3d6 .8px, transparent .8px),
    radial-gradient(circle at 80px 150px, #f0ece1 2px, transparent 2px);
  background-size: 36px 36px, 160px 160px;
  line-height:1.65;
  display:flex;
  flex-direction:column;
  min-height:100vh;
  -webkit-font-smoothing:antialiased;
}
a{color:var(--primary);text-decoration:none}
a:hover{text-decoration:underline}
img{max-width:100%;height:auto;display:block}

/* --- SKETCH DIVIDER --- */
.sketch-divider{
  width:120px;height:4px;
  background:var(--primary);
  border-radius:2px;
  margin:0 auto 1rem;
}

/* --- HEADER --- */
.site-header{
  background:rgba(255,255,255,.92);
  backdrop-filter:blur(16px) saturate(1.2);
  border-bottom:3px solid var(--primary);
  padding:0 1rem;
  position:sticky;
  top:0;
  z-index:100;
}
.nav-wrap{
  max-width:1200px;
  margin:0 auto;
  display:flex;
  align-items:center;
  justify-content:space-between;
  height:72px;
}
.logo{
  font-size:1.4rem;
  font-weight:900;
  letter-spacing:-1px;
  background:linear-gradient(135deg,var(--primary-dark),var(--primary));
  -webkit-background-clip:text;
  -webkit-text-fill-color:transparent;
  background-clip:text;
}
.logo span{font-weight:400;color:var(--text-muted);-webkit-text-fill-color:var(--text-muted);}
.logo:hover{text-decoration:none}
.nav-links{display:flex;gap:.3rem;list-style:none;align-items:center}
.nav-links a{
  color:var(--text);
  font-weight:600;
  font-size:.85rem;
  padding:.4rem 1rem;
  border-radius:50px;
  transition:.2s;
  letter-spacing:.2px;
}
.nav-links a:hover,.nav-links a.active{
  color:#fff;
  background:var(--primary);
  text-decoration:none;
}
.nav-toggle{display:none;background:none;border:none;font-size:1.6rem;cursor:pointer;color:var(--text);padding:.25rem;}

/* --- MAIN --- */
main{flex:1;width:100%}

/* --- HERO MEGA --- */
.hero-mega{
  max-width:1200px;
  margin:2rem auto 0;
  padding:0 1rem;
  position:relative;
}
.hero-inner{
  background:linear-gradient(160deg,#fff8f0,#fff3e0 40%,#ffe0b2);
  border-radius:var(--radius-xl);
  padding:4rem 3rem;
  position:relative;
  overflow:hidden;
  border:var(--sketch);
}
/* Decorative sketch blobs */
.hero-inner::before{
  content:'🐾';
  position:absolute;
  top:30px;right:60px;
  font-size:6rem;
  opacity:.08;
  transform:rotate(15deg);
}
.hero-inner::after{
  content:'🐾';
  position:absolute;
  bottom:-20px;left:40px;
  font-size:8rem;
  opacity:.06;
  transform:rotate(-10deg);
}
.hero-badge{
  display:inline-flex;
  align-items:center;
  gap:.5rem;
  background:rgba(255,152,0,.12);
  color:var(--primary-dark);
  font-size:.78rem;
  font-weight:700;
  padding:.35rem 1rem;
  border-radius:50px;
  letter-spacing:.5px;
  text-transform:uppercase;
  margin-bottom:1.2rem;
}
.hero-grid{
  display:grid;
  grid-template-columns:1.2fr 1fr;
  gap:3rem;
  align-items:center;
  position:relative;
  z-index:1;
}
.hero-text h1{
  font-family:var(--font-display);
  font-size:3.2rem;
  line-height:1.15;
  color:var(--primary-dark);
  margin-bottom:1rem;
  font-weight:400;
}
.hero-text h1 strong{color:var(--text);font-weight:400;}
.hero-text p{
  font-size:1.1rem;
  color:var(--text-muted);
  line-height:1.6;
  margin-bottom:2rem;
  max-width:520px;
}
.hero-actions{
  display:flex;
  gap:.8rem;
  flex-wrap:wrap;
}
.btn{
  display:inline-flex;
  align-items:center;
  gap:.5rem;
  font-weight:700;
  font-size:.9rem;
  padding:.75rem 1.6rem;
  border-radius:50px;
  border:none;
  cursor:pointer;
  transition:.25s;
  font-family:var(--font);
  text-decoration:none;
}
.btn-primary{
  background:var(--primary);
  color:#fff;
  box-shadow:0 4px 14px var(--primary-glow);
}
.btn-primary:hover{background:var(--primary-dark);transform:translateY(-2px);text-decoration:none}
.btn-outline{
  background:transparent;
  color:var(--text);
  border:2px solid var(--border);
}
.btn-outline:hover{border-color:var(--primary);color:var(--primary);text-decoration:none;transform:translateY(-2px)}
.btn-outline-light{
  background:rgba(255,255,255,.7);
  color:var(--text);
  backdrop-filter:blur(4px);
}
.btn-outline-light:hover{background:#fff;text-decoration:none}
.hero-visual{
  display:grid;
  grid-template-columns:1fr 1fr;
  gap:.8rem;
}
.hero-visual .card-img{
  border-radius:var(--radius-md);
  overflow:hidden;
  box-shadow:0 4px 20px rgba(0,0,0,.08);
  aspect-ratio:4/3;
}
.hero-visual .card-img img{width:100%;height:100%;object-fit:cover;transition:transform .5s}
.hero-visual .card-img:hover img{transform:scale(1.06)}
.hero-visual .card-img:first-child{grid-column:1/-1;aspect-ratio:16/9}

/* --- STATS BAR --- */
.stats-bar{
  max-width:1200px;
  margin:0 auto;
  padding:0 1rem;
  transform:translateY(-50%);
  position:relative;
  z-index:2;
}
.stats-inner{
  background:var(--bg-white);
  border-radius:var(--radius-md);
  box-shadow:var(--card-shadow);
  border:2px solid var(--border-light);
  display:grid;
  grid-template-columns:repeat(4,1fr);
  padding:1.8rem 2rem;
  gap:1rem;
}
.stat-item{
  text-align:center;
  border-right:1px solid var(--border-light);
  padding:.5rem;
}
.stat-item:last-child{border-right:none}
.stat-num{
  font-family:var(--font-display);
  font-size:2rem;
  font-weight:400;
  color:var(--primary-dark);
  line-height:1.2;
}
.stat-label{
  font-size:.82rem;
  color:var(--text-muted);
  font-weight:500;
  letter-spacing:.3px;
}

/* --- SECTION COMMON --- */
.section-wrap{
  max-width:1200px;
  margin:0 auto;
  padding:0 1rem;
}
.section-pad{padding:4rem 0}
.section-header{
  text-align:center;
  margin-bottom:3rem;
}
.section-header h2{
  font-family:var(--font-display);
  font-size:2.2rem;
  color:var(--text);
  margin-bottom:.5rem;
  font-weight:400;
}
.section-header p{
  color:var(--text-muted);
  font-size:1.05rem;
  max-width:600px;
  margin:0 auto;
}

/* --- CATEGORY CARDS --- */
.cat-grid{
  display:grid;
  grid-template-columns:repeat(3,1fr);
  gap:1.5rem;
  margin-bottom:4rem;
}
.cat-card{
  background:#fff;
  border:2px solid var(--border-light);
  border-radius:var(--radius-lg);
  padding:2.5rem 2rem;
  text-align:center;
  transition:.3s;
  cursor:pointer;
  position:relative;
  overflow:hidden;
}
.cat-card:hover{transform:translateY(-6px);box-shadow:var(--card-shadow-hover);border-color:var(--primary-light)}
.cat-icon{
  font-size:3.2rem;
  margin-bottom:1rem;
  display:block;
}
.cat-card h3{font-size:1.4rem;font-weight:700;margin-bottom:.5rem;color:var(--text)}
.cat-card p{font-size:.88rem;color:var(--text-muted);margin-bottom:1rem;line-height:1.5}
.cat-count{
  font-size:.78rem;
  font-weight:700;
  color:var(--primary);
  text-transform:uppercase;
  letter-spacing:.5px;
}
.cat-card::after{
  content:'';
  position:absolute;
  bottom:0;left:20%;right:20%;
  height:3px;
  background:var(--primary);
  border-radius:3px 3px 0 0;
  transform:scaleX(0);
  transition:.3s;
}
.cat-card:hover::after{transform:scaleX(1)}

/* --- FEATURED ARTICLES --- */
.featured-grid{
  display:grid;
  grid-template-columns:1.4fr 1fr 1fr;
  grid-template-rows:auto auto;
  gap:1.2rem;
  margin-bottom:4rem;
}
.featured-grid .blog-card:first-child{
  grid-row:1/3;
}
.featured-grid .blog-card:first-child .card-img{height:320px}
.featured-grid .blog-card:first-child h2{font-size:1.4rem}
.featured-grid .blog-card:first-child p{font-size:.95rem}

/* --- BLOG CARD (shared) --- */
.blog-card{
  background:#fff;
  border:2px solid var(--border-light);
  border-radius:var(--radius-md);
  overflow:hidden;
  box-shadow:var(--card-shadow);
  transition:.3s;
  display:flex;
  flex-direction:column;
}
.blog-card:hover{transform:translateY(-4px);box-shadow:var(--card-shadow-hover);border-color:var(--primary-light)}
.card-img{
  width:100%;
  height:200px;
  background:var(--bg-alt);
  overflow:hidden;
  flex-shrink:0;
}
.card-img img{width:100%;height:100%;object-fit:cover;transition:transform .5s}
